function AccountDetail({id,query}){const r=useResource(`/admin/accounts/${encodeURIComponent(id)}`);if(r.error)return <LoadError error={r.error} retry={r.reload}/>;if(!r.data)return <Busy/>;const d=r.data;return <section className="account-detail"><a href={adminHref('accounts')}>Back to accounts</a><h2>{d.account.name||d.account.email}</h2><p>{d.account.email} · {d.account.role}</p><nav className="trace-links" aria-label="Account operations"><a href={adminHref('activity',{userId:id})}>Activity owned by this account</a><a href={adminHref('activity',{actorId:id})}>Actions performed by this account</a><a href={adminHref('jobs',{userId:id})}>Owned jobs</a><a href={adminHref('reviews',{userId:id})}>Owned decisions</a></nav><div className="metrics"><div><strong>{d.counts.attempts}</strong><span>Recorded answers</span></div><div><strong>{d.counts.bktHistory}</strong><span>BKT updates</span></div><div><strong>{d.counts.reviewHistory}</strong><span>Recall reviews</span></div><div><strong>{d.counts.vocabulary}</strong><span>Review cards</span></div></div><details className="data-detail"><summary>Current objective estimates and placement</summary><div className="table-wrap"><table><thead><tr><th>Objective</th><th>Version</th><th>Estimate</th><th>Decision</th></tr></thead><tbody>{d.objectives.map(o=><tr key={o.id}><td>{o.label}<small>{o.id}</small></td><td>{o.version}</td><td>{estimate(o.probability)}</td><td>{o.status}<small>{o.reason}</small></td></tr>)}</tbody></table></div><DataDetail label="Placement and assessed objectives" data={d.placement}/><DataDetail label="Daily quota use" data={d.quotas}/></details><p className="muted">Estimates are provisional, not validated proficiency scores. Historical updates are preserved as recorded. FSRS recall ratings do not update BKT objective estimates; these are separate histories, not additive evidence.</p><nav className="trace-links" aria-label="Account histories">{Object.entries(historyLabels).map(([type,label])=><a key={type} aria-current={(query.type||'attempts')===type?'page':undefined} href={adminHref('accounts',{account:id,type})}>{label}</a>)}</nav><AdminTrace tab="accounts" query={{...query,type:query.type||'attempts'}} account={id}/></section>}
function AdminEvent({event:e}){const d=e.data||{},curriculum=d.result?.curriculum,bookId=d.bookId||d.input?.book?.id;return <article className="trace-record"><header><h3>{e.kind==='ai'?`AI ${d.task||'invocation'}: ${d.phase||'phase unavailable'}`:`${e.kind}: ${d.event||d.node||d.decision||'recorded'}`}</h3><span className="pill">{d.status||d.state||d.to||'Recorded'}</span></header><p className="muted">{date(e.createdAt)}</p>{(d.reason||d.message||d.error||d.output?.reason)&&<p>{traceText(d.reason||d.message||d.error||d.output?.reason).slice(0,500)}</p>}<TraceFields fields={e.kind==='ai'?[['Task',d.task],['Model',d.model],['Prompt version',d.promptVersion],['Tool',d.tool],['Elapsed milliseconds',d.elapsedMs],['Provider usage',d.usage]]:[['From',d.from],['To',d.to],['Decision',d.decision]]}/><TraceLinks owner={e.ownerId} ownerName={e.ownerName} actor={e.userId} actorName={e.actorName} jobId={e.jobId} reviewId={d.reviewId} bookId={bookId} curriculum={d.version??curriculum?.version} lessonIds={d.lessonIds||curriculum?.lessons?.map(l=>l.id)||[]}/><DataDetail label={`Raw event: ${e.id}`} data={e}/></article>}
function AdminJob({job,onChange}){const [error,setError]=useState(''),[busy,setBusy]=useState(false),curriculum=job.result?.curriculum;return <article className="admin-job"><div className="admin-job-head"><h3>{job.kind} job</h3><span className="pill">{statusLabel(job.status)}</span></div><p>{job.message||job.error}</p>{curriculum?.reason&&<p>{curriculum.reason}</p>}<TraceFields fields={ [['Created',date(job.createdAt)],['Updated',date(job.updatedAt)],['Progress',`${Math.round(job.progress*100)}%`],['Revision',curriculum?.version]] }/><TraceLinks owner={job.userId} ownerName={job.ownerName} reviewId={job.result?.reviewId} bookId={job.bookId} curriculum={curriculum?.version} lessonIds={curriculum?.lessons?.map(l=>l.id)||[]}/><nav className="trace-links" aria-label="Job trace"><a href={adminHref('activity',{jobId:job.id})}>Activity for this job</a><a href={adminHref('reviews',{jobId:job.id})}>Decisions for this job</a></nav><DataDetail label={`Raw job: ${job.id}`} data={job}/>{['queued','running'].includes(job.status)&&<Button secondary disabled={busy} onClick={async()=>{setBusy(true);try{await post(`/jobs/${job.id}/cancel`);onChange()}catch(e){setError(e.message)}finally{setBusy(false)}}}>{busy?'Cancelling…':'Cancel this job'}</Button>}<Notice error>{error}</Notice></article>}
function AdminReview({review,onChange}){const [reason,setReason]=useState(''),[decision,setDecision]=useState('reject'),[busy,setBusy]=useState(false),[error,setError]=useState(''),resolution=review.resolution,curriculum=resolution?.result?.curriculum;return <article className="admin-review"><div className="admin-job-head"><h3>{review.kind==='curriculum'?'Proposed curriculum':'Content feedback'}</h3><span className="pill">{review.status}</span></div><p>{resolution?.reason||review.data?.reason||review.data?.message||'Review the retained evidence below.'}</p><TraceFields fields={ [['Created',date(review.createdAt)],['Decision',resolution?.decision],['Reviewer',resolution?.reviewer],['Resulting revision',curriculum?.version]] }/><TraceLinks owner={review.userId} ownerName={review.ownerName} actor={resolution?.reviewer} jobId={review.data?.jobId} bookId={review.bookId} curriculum={curriculum?.version} lessonIds={curriculum?.lessons?.map(l=>l.id)||[]}/><nav className="trace-links" aria-label="Decision trace"><a href={adminHref('activity',{reviewId:review.id})}>Activity for this decision</a></nav><DataDetail label="Evidence and proposed content" data={review.data} open={review.status==='pending'}/>{review.status==='pending'?<form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await post(`/admin/reviews/${review.id}/resolve`,{decision,reason});onChange()}catch(e){setError(e.message)}finally{setBusy(false)}}}><p>Before approving this exact proposal, check source grounding, Spanish accuracy, the answer key, and the assessed skill. Structural validation alone is not semantic review.</p><label>Decision<select value={decision} onChange={e=>setDecision(e.target.value)}><option value="reject">Reject proposal / close without change</option><option value="approve">Approve reviewed content</option></select></label><label>Review reason<textarea required value={reason} rows="3" maxLength="3000" onChange={e=>setReason(e.target.value)} placeholder="Record what you checked and why this decision is justified."/></label><Notice error>{error}</Notice><Button disabled={busy||!reason.trim()}>{busy?'Recording…':'Record resolution'}</Button></form>:<DataDetail label="Recorded decision, reviewer and resulting version" data={resolution}/>}<DataDetail label={`Raw review: ${review.id}`} data={review}/></article>}
function AdminHistoryRow({row:r,type,account}){const d=r.data||{},lessonId=r.context?.startsWith('lesson:')?r.context.slice(7):null,title=type==='attempts'?`${r.correct?'Correct':'Incorrect'} answer${r.scored?' · scored':' · not scored'}`:type==='bktHistory'?`Objective estimate: ${estimate(d.prior)} to ${estimate(d.posterior)}`:type==='reviewHistory'?`Recall: ${d.item?.front||r.itemId}`:type==='vocabulary'?r.front:d.title||historyLabels[type],fields=type==='attempts'?[['Question',r.questionId],['Question version',r.questionVersion],['Objective',r.objectiveId],['Objective version',r.objectiveVersion],['Assistance',r.assisted?'Assisted':'Unassisted']]:type==='bktHistory'?[['Objective',r.objectiveId],['Parameter version',d.parameters?.version],['Question version',d.questionVersion],['Objective version',d.objectiveVersion],['Observed outcome',d.correct===true?'Correct':d.correct===false?'Incorrect':null]]:type==='reviewHistory'?[['Rating',({1:'Again',2:'Hard',3:'Good',4:'Easy'})[d.rating]],['Scheduler',d.scheduler],['Next due',date(d.card?.due||d.item?.due)],['BKT update',d.bktUpdated===false?'No — recall scheduling only':'Unavailable']]:type==='vocabulary'?[['Answer and explanation',r.back],['Due',date(r.due)],['Estimated retention now',estimate(r.retrievability)]]:type==='books'?[['Book',r.id],['Status',r.status||d.status],['Source',r.source||'Stored account source']]:[['Revision',r.version||d.version],['Book',r.bookId],['Record',r.id]];return <article className="trace-record"><header><h3>{title}</h3></header><p className="muted">{r.source||date(r.createdAt)}</p>{(d.reason||d.explanation)&&<p>{traceText(d.reason||d.explanation).slice(0,500)}</p>}<TraceFields fields={fields}/>{type==='bktHistory'&&<a href={adminHref('accounts',{account,type:'attempts',id:r.attemptId})}>View the answer behind this update</a>}{type==='attempts'&&<a href={adminHref('accounts',{account,type:'bktHistory',attemptId:r.id})}>View BKT updates for this answer</a>}{type==='reviewHistory'&&<a href={adminHref('accounts',{account,type:'vocabulary',id:r.itemId})}>View review card</a>}<TraceLinks owner={account} ownerLabel={r.source?'Account context':'Owner'} bookId={r.bookId||d.item?.bookId} curriculum={r.version} lessonIds={lessonId?[lessonId]:type==='curricula'?d.lessons?.map(l=>l.id)||[]:[]}/>{type==='lessons'&&<a href={adminHref('accounts',{account,type:'attempts',context:`lesson:${r.id}`})}>Answers from this lesson</a>}<DataDetail label={`Raw ${historyLabels[type]||'record'}: ${r.id}`} data={r}/></article>}
createRoot(document.getElementById('root')).render(<App/>);
